def verifier(assign):
    import math
    def gcd(a,b):
        return math.gcd(a,b)
    def lcm(a,b):
        return a // gcd(a,b) * b
    def reduce_frac(num, den):
        g = gcd(abs(num), abs(den))
        num //= g
        den //= g
        if den < 0:
            num = -num
            den = -den
        return num, den
    # extract
    try:
        m = int(assign['m'])
        n = int(assign['n'])
        u = int(assign['u'])
        v = int(assign['v'])
        c = int(assign['c'])
        r_num = int(assign['r_num'])
        r_den = int(assign['r_den'])
    except Exception:
        # invalid assignment
        return (False, None)
    # basic checks
    if not (m > n > 0 and u > v > 0):
        return (False, None)
    if any(x % 2 == 0 for x in [m, n, u, v]):
        return (False, None)
    if gcd(m,n) != 1 or gcd(u,v) != 1:
        return (False, None)
    # build s via the constructive mapping
    S = 2 * (u + v) * (u + v)
    if S % (m + n) != 0:
        # our construction requires this divisibility
        return (False, None)
    p = S // (m + n)
    q = (u - v) * (u - v) - ((n - m) * p) // 2
    if q <= 0:
        return (False, None)
    # s = p/q reduced
    g0 = gcd(p, q)
    p0 = p // g0
    q0 = q // g0
    if not (0 < p0 < q0):
        return (False, None)
    # parameters
    a = (m * m + n * n) // 2
    b = m - n
    # t from formula: t = 2*(p0 + q0)/M - 1, M=u^2+v^2
    M = u * u + v * v
    t_num = 2 * (p0 + q0)
    t_den = M
    # bounds ensure 0<t<1
    if not (t_num > t_den and t_num < 2 * t_den):
        return (False, None)
    # reduce t = (t_num - t_den)/t_den
    tN, tD = reduce_frac(t_num - t_den, t_den)
    # compute rational expressions to validate the key identity exactly:
    # LHS: (1 + a s^2 - b s)/2 = (q0^2 + a p0^2 - b p0 q0) / (2 q0^2)
    lhs_num = q0 * q0 + a * p0 * p0 - b * p0 * q0
    lhs_den = 2 * q0 * q0
    lhs_num, lhs_den = reduce_frac(lhs_num, lhs_den)
    # RHS: ((1 + s)/(1 + t))^2
    # (1+s) = (p0 + q0)/q0; (1+t) = (tN + tD)/tD = t_num / t_den
    rhs_num = (p0 + q0) * tD
    rhs_den = q0 * t_num
    # square RHS
    rhs_num2 = rhs_num * rhs_num
    rhs_den2 = rhs_den * rhs_den
    rhs_num2, rhs_den2 = reduce_frac(rhs_num2, rhs_den2)
    # Check equality
    if lhs_num * rhs_den2 != rhs_num2 * lhs_den:
        return (False, None)
    # compute x, y
    x_num = q0 * q0 - p0 * p0
    x_den = 2 * q0 * q0
    x_num, x_den = reduce_frac(x_num, x_den)
    y_num = tD * tD - tN * tN
    y_den = 2 * tD * tD
    y_num, y_den = reduce_frac(y_num, y_den)
    # ensure 0 < x,y < 1/2
    if not (x_num > 0 and y_num > 0):
        return (False, None)
    # ratio R = (1+s)/(1+t) = M/(2 q0)
    R_num, R_den = reduce_frac(M, 2 * q0)
    # minimal k
    k = lcm(x_den, y_den)
    k = lcm(k, R_den)
    # require nontrivial size
    if k < 100:
        return (False, None)
    answer = f"### The final answer is: $\\boxed{{{k}}}$"
    return (True, answer)
